select date_format(start_date, 'yyyy-MM') as start_month, case when status in ('PAUSED', 'EXPIRED') then 'group_a' else 'other' end as status_group, round(stddev(monthly_fee), 2) as stddev_monthly_fee, max(monthly_fee) - min(monthly_fee) as monthly_fee_range from subscriptions where status in ('ACTIVE', 'EXPIRED', 'CANCELLED') group by start_month, status_group having round(stddev(monthly_fee), 2) >= 39 order by status_group;
